				border-radius: 50%;
				width: 24px;
				height: 24px;
				background: #090527;
				border-width: 0px;
				border-style: solid;
				border-color: #ffffff;
				position: absolute;
				top: 24px;
				right: 24px;
				z-index: 100;
				display: flex;
				align-items: center;
				justify-content: center;
			}

			img {
				width: 50% !important;
				margin: 0px auto !important;
				z-index: 3;
				border: 1px solid #555555;
				border-radius: 12px;
				vertical-align: middle;
			}

			dl, ol, ul {
				margin-top: 0;
				margin-bottom: 1rem;
				text-align: left;
			}

			ol ol, ol ul, ul ol, ul ul {
				margin-bottom: 0
			}

			b, strong {
				font-weight: bolder
			}

			sub, sup {
				position: relative;
				font-size: 75%;
				line-height: 0;
				vertical-align: baseline
			}

			sub {
				bottom: -.25em
			}

			sup {
				top: -.5em
			}

			a {
				color: #FE5000;
				text-decoration: none;
				background-color: transparent;
				-webkit-text-decoration-skip: objects
			}

			#headline {
				box-sizing: border-box;
				z-index: 3;
				color: #090527;
				text-align: center;
				font-family: 'MaisonNeueExtended-Demi';
				font-size: 16px;
				line-height: normal;
				letter-spacing: normal;
				width: 100%;
				padding-right: 35px;
				padding-left: 35px;
				margin-top: 5%;
				margin-bottom: 10px;
			}

			#body-copy {
				box-sizing: border-box;
				z-index: 3;
				color: #757575;
				text-align: center;
				font-size: 14px;
				line-height: normal;
				letter-spacing: normal;
				width: 100%;
				padding-right: 35px;
				padding-left: 35px;
				margin-top: 5px;
				margin-bottom: 20px;
			}

			#create-account {
				background: #fe5000;
				background-position: center;
				background-repeat: no-repeat;
				background-size: cover;
				display: flex;
				border: 1px solid #fe5000;
				justify-self: center;
				color: #FFFFFF;
				width: 100%;
				border-radius: 60px;
				height: 45px;
				flex-direction: column;
				justify-content: center;
			}

			#button_container {
				box-sizing: border-box;
				z-index: 3;
				text-align: center;
				font-family: 'MaisonNeue-bold';
				font-size: 12px;
				letter-spacing: 0px;
				padding-right: 35px;
				padding-left: 35px;
				background: transparent;
				justify-content: center;
				align-items: center;
				display: flex;
				width: 100% !important;
				flex-wrap: wrap;
				flex-direction: column;
			}
		</style>
